s: stretch;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 2px;
}
.twf-arrow {
  align-self: center;
  color: #64748b;
  font-size: 13px;
  font-weight: 700;
  flex-shrink: 0;
}
.twf-stage-pill {
  flex: 1 1 135px;
  min-width: 125px;
  padding: 6px 9px;
  border-radius: 7px;
  background: rgba(30, 41, 59, 0.78);
  border: 1px solid rgba(71, 85, 105, 0.65);
  cursor: pointer;
  transition: all 0.15s ease;
}
.twf-stage-pill:hover,
.twf-stage-pill.active-stage-pill {
  border-color: #38bdf8;
  background: rgba(14, 116, 144, 0.24);
}
.twf-stage-pill.status-done {
  border-color: rgba(16, 185, 129, 0.45);
}
.twf-stage-pill.status-running {
  border-color: #38bdf8;
  box-shadow: 0 0 0 1px rgba(56, 189, 248, 0.35);
}
.twf-stage-pill.status-waiting {
  border-color: rgba(245, 158, 11, 0.65);
  background: rgba(120, 53, 15, 0.22);
}
.twf-stage-top {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  font-weight: 700;
  color: #f1f5f9;
}
.twf-stage-icon {
  color: #34d399;
  font-weight: 800;
}
.twf-stage-pill.status-waiting .twf-stage-icon {
  color: #fbbf24;
}
.twf-stage-pill.status-pending .twf-stage-icon {
  color: #64748b;
}
.twf-stage-badge {
  margin-left: auto;
  font-size: 9.5px;
  padding: 1px 5px;
  border-radius: 4px;
  background: rgba(59, 130, 246, 0.2);
  color: #93c5fd;
}
.twf-stage-sub {
  margin-top: 2px;
  font-size: 10.5px;
  color: #94a3b8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Wave 0..N Sub-Tasks Strip inside #autopilot-flow */
.twf-wave-box {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 5px 8px;
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.92);
  border: 1px solid rgba(56, 189, 248, 0.3);
  min-width: 170px;
}
.twf-wave-hdr {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 10.5px;
  font-weight: 700;
  color: #7dd3fc;
}
.twf-wave-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.twf-subtask-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px;
  border-radius: 5px;
  font-size: 10.5px;
  background: rgba(30, 41, 59, 0.9);
  border: 1px solid rgba(100, 116, 139, 0.55);
  color: #e2e8f0;
  cursor: pointer;
}
.twf-subtask-chip:hover,
.twf-subtask-chip.active-subtask-chip {
  border-color: #38bdf8;
  background: rgba(14, 116, 144, 0.32);
}
.twf-subtask-chip.status-done {
  border-color: rgba(16, 185, 129, 0.55);
  color: #a7f3d0;
}
.twf-subtask-chip.status-running {
  border-color: #38bdf8;
  color: #bae6fd;
}
.twf-st-id {
  font-weight: 800;
  color: #38bdf8;
}
.twf-st-title {
  max-width: 150px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.twf-st-repo {
  font-size: 9.5px;
  color: #94a3b8;
}

/* Zone 3: Clean Tabbed Workspace Modes (No Stacked 7-Box Clutter!) */
.sri-tab[data-step="TRACE"] {
  border-color: rgba(16, 185, 129, 0.45);
  color: #6ee7b7;
  font-weight: 800;
}
.sri-tab[data-step="TRACE"].active {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.28), rgba(6, 182, 212, 0.25));
  border-color: #10b981;
  color: #ecfdf5;
}
#hdr-repo-memory-badge {
  background: rgba(16, 185, 129, 0.16);
  border: 1px solid rgba(16, 185, 129, 0.45);
  color: #6ee7b7;
}

/* Trace Session Selector Strip inside TRACE tab */
.trace-session-selector-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 7px 10px;
  background: rgba(15, 23, 42, 0.92);
  border-bottom: 1px solid rgba(51, 65, 85, 0.75);
}
.trace-session-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border-radius: 6px;
  font-size: 11px;
  background: rgba(30, 41, 59, 0.9);
  border: 1px solid rgba(71, 85, 105, 0.7);
  color: #e2e8f0;
  cursor: pointer;
}
.trace-session-pill.green .ts-status {
  color: #34d399;
  font-weight: 700;
}
.trace-session-pill.red {
  border-color: rgba(239, 68, 68, 0.55);
}
.trace-session-pill.red .ts-status {
  color: #f87171;
  font-weight: 700;
}
.trace-session-pill.active-trace-pill {
  background: rgba(16, 185, 129, 0.22);
  border-color: #10b981;
}

/* Mode 1 & 2 (TRACE / S1..S5): Hide stacked .sri-subtasks-box, #co-architect-studio, and .autopilot-split-bottom */
#step-report-inspector-card:not([data-active-tab="SUBTASKS"]) .sri-subtasks-box {
  display: none !important;
}
#step-report-inspector-card:not([data-active-tab="STUDIO"]) #co-architect-studio {
  display: none !important;
}
#screen-autopilot:not([data-active-tab="STUDIO"]) .autopilot-split-bottom {
  display: none !important;
}
#step-report-inspector-card:not([data-active-tab="SUBTASKS"]) #sri-code-demo-content {
  flex: 1 1 0 !important;
  max-height: none !important;
  min-height: 460px !important;
}

/* Mode 3 (SUBTASKS Tab): Full-width Sub-Tasks & Fractal Inspector */
#step-report-inspector-card[data-active-tab="SUBTASKS"] .sri-body {
  grid-template-columns: 1fr !important;
}
#step-report-inspector-card[data-active-tab="SUBTASKS"] .sri-markdown-pane,
#step-report-inspector-card[data-active-tab="SUBTASKS"] #sri-side-pane > .sri-pane-hdr,
#step-report-inspector-card[data-active-tab="SUBTASKS"] #sri-code-demo-content {
  display: none !important;
}
#step-report-inspector-card[data-active-tab="SUBTASKS"] .sri-subtasks-box {
  margin-top: 0 !important;
  border-top: none !important;
}

/* Mode 4 (STUDIO Tab): Clean Co-Architect Chat + Live Task Execution Log */
#step-report-inspector-card[data-active-tab="STUDIO"] #sri-body-container {
  display: none !important;
}
#step-report-inspector-card[data-active-tab="STUDIO"] .cas-quick-prompts,
#step-report-inspector-card[data-active-tab="STUDIO"] .cas-sub-hint,
#step-report-inspector-card[data-active-tab="STUDIO"] .btn-cas-approve {
  display: none !important;
}
#screen-autopilot[data-active-tab="STUDIO"] .autopilot-split-bottom {
  display: grid !important;
  grid-template-columns: 1fr !important;
  margin-top: 8px !important;
}
#screen-autopilot[data-active-tab="STUDIO"] .autopilot-ledger-col {
  display: none !important;
}
